<template>
  <div class="page">
    <div class="page-head">
      <div><h2>{{ title }}</h2><p>{{ subtitle }}</p></div>
      <div class="actions">
        <el-button v-if="section==='devices'&&can('access.device.manage')" @click="editPoint()">新增门禁点</el-button>
        <el-button v-if="section==='devices'&&can('access.device.manage')" type="primary" @click="editDevice()">新增设备</el-button>
        <el-button v-if="section==='devices'&&can('access.sync.import')" :loading="scan.status==='PENDING'||scan.status==='RUNNING'" type="success" @click="startPersonScan">扫描人员并比对</el-button>
        <el-button v-if="section==='devices'&&can('access.sync.import')" :loading="cardScan.status==='PENDING'||cardScan.status==='RUNNING'" type="success" plain @click="startCardScan">扫描卡片并比对</el-button>
        <el-button v-if="section==='persons'&&can('access.person.manage')" type="primary" @click="editPerson()">新增人员</el-button>
        <el-button v-if="section==='visitors'&&can('visitor.create')" type="primary" @click="openVisitor">发起预约</el-button>
        <el-button v-if="section==='events'&&can('access.event.sync')" type="primary" :loading="eventSyncing" @click="syncEvents">立即同步通行记录</el-button>
        <el-button v-if="section==='reviews'" type="primary" @click="generateReview">生成未通行复核</el-button>
      </div>
    </div>

    <template v-if="section==='dashboard'">
      <div class="cards">
        <div v-for="c in cards" :key="c.key" class="card"><span>{{ c.label }}</span><strong>{{ dashboard[c.key]||0 }}</strong></div>
      </div>
      <section class="panel"><h3>最近通行</h3><event-table :rows="dashboard.recentEvents||[]" :photo-urls="eventPhotoUrls" @snapshot="showEventSnapshot" /></section>
    </template>

    <template v-else-if="section==='self'">
      <el-alert v-if="!selfData.person?.id" title="请使用设备存量资料中的手机号和身份证号认领本人档案。" type="warning" show-icon :closable="false" />
      <el-button v-if="!selfData.person?.id" class="self-create" type="primary" @click="claimVisible=true">认领我的人员档案</el-button>
      <section v-else class="panel profile">
        <div class="profile-head"><h3>{{ selfData.person.personName }}</h3><div class="actions"><el-button @click="requestRenewal">申请续期一年</el-button><el-button type="primary" @click="editSelf">维护我的信息</el-button></div></div>
        <el-descriptions :column="mobile?1:3" border>
          <el-descriptions-item label="人员编号">{{ selfData.person.personNo }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ selfData.person.phone||'-' }}</el-descriptions-item><el-descriptions-item label="身份证号">{{ selfData.person.idNumber||'-' }}</el-descriptions-item><el-descriptions-item label="单位/部门">{{ selfData.person.organizationName||'-' }} {{ selfData.person.departmentName||'' }}</el-descriptions-item><el-descriptions-item label="有效期">{{ fmt(selfData.person.validFrom) }} 至 {{ fmt(selfData.person.validTo) }}</el-descriptions-item><el-descriptions-item label="人脸状态">{{ label.face[selfData.person.faceStatus]||selfData.person.faceStatus }}</el-descriptions-item><el-descriptions-item label="人员状态">{{ label.person[selfData.person.personStatus]||selfData.person.personStatus }}</el-descriptions-item>
        </el-descriptions>
      </section>
      <section class="panel"><h3>我的通行记录</h3><event-table :rows="selfData.events||[]" :photo-urls="eventPhotoUrls" @snapshot="showEventSnapshot" /></section>
      <section class="panel"><h3>我的访客预约</h3><visitor-table :rows="selfData.appointments||[]" /></section>
      <section class="panel"><h3>我的续期申请</h3><renewal-table :rows="selfData.renewals||[]" /></section>
    </template>

    <template v-else-if="section==='devices'">
      <section class="panel"><h3>门禁点</h3><el-table :data="points"><el-table-column prop="pointCode" label="编码"/><el-table-column prop="pointName" label="名称"/><el-table-column prop="location" label="位置" min-width="150"/><el-table-column prop="floorCode" label="楼层"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column v-if="can('access.device.manage')" label="操作" width="80"><template #default="s"><el-button link type="primary" @click="editPoint(s.row)">编辑</el-button></template></el-table-column></el-table></section>
      <section class="panel"><div class="safe-tip"><b>设备写入保护</b><span>仅超级管理员可逐台开启；开启后，审批与撤销才会同步人员和人脸。</span></div><el-table :data="devices"><el-table-column prop="pointName" label="门禁点"/><el-table-column prop="deviceName" label="设备名称" min-width="140"/><el-table-column label="方向"><template #default="s">{{label.direction[s.row.direction]||s.row.direction}}</template></el-table-column><el-table-column prop="model" label="型号"/><el-table-column prop="serialNumber" label="序列号" min-width="210"/><el-table-column prop="ipAddress" label="IP地址"/><el-table-column label="在线"><template #default="s"><el-tag :type="s.row.onlineStatus==='ONLINE'?'success':'info'">{{label.online[s.row.onlineStatus]||s.row.onlineStatus}}</el-tag></template></el-table-column><el-table-column label="写入状态"><template #default="s"><el-switch v-if="can('access.sync.write')" :model-value="!s.row.readOnlyMode" active-text="可写" inactive-text="只读" @change="setWriteMode(s.row,$event)"/><el-tag v-else :type="s.row.readOnlyMode?'warning':'danger'">{{s.row.readOnlyMode?'只读':'可写'}}</el-tag></template></el-table-column><el-table-column v-if="can('access.device.manage')" label="操作" width="130"><template #default="s"><el-button link type="success" @click="discoverDevice(s.row)">探测</el-button><el-button link type="primary" @click="editDevice(s.row)">编辑</el-button></template></el-table-column></el-table></section>
      <section v-if="scan.id" class="panel"><div class="scan-head"><h3>存量人员比对</h3><el-tag :type="scan.status==='COMPLETED'?'success':scan.status==='FAILED'?'danger':'warning'">{{scanStatus[scan.status]||scan.status}}</el-tag></div><el-progress v-if="scan.status==='PENDING'||scan.status==='RUNNING'" :percentage="scan.deviceTotal?Math.round((scan.deviceCompleted||0)*100/scan.deviceTotal):0" :indeterminate="!scan.deviceTotal"/><div v-if="scan.status==='COMPLETED'" class="scan-cards"><div><b>{{scan.uniquePersons}}</b><span>去重后人员</span></div><div><b>{{scan.commonPersons}}</b><span>两端共有</span></div><div><b>{{scan.onlyEntry}}</b><span>仅入口</span></div><div><b>{{scan.onlyExit}}</b><span>仅出口</span></div><div><b>{{scan.conflictPersons}}</b><span>资料冲突</span></div></div><p class="muted">{{scan.message}}</p><el-table v-if="scan.differences?.length" :data="scan.differences" max-height="360"><el-table-column prop="employeeNo" label="人员编号" min-width="130"/><el-table-column prop="entryName" label="入口姓名"/><el-table-column prop="exitName" label="出口姓名"/><el-table-column label="入口有效期"><template #default="s">{{fmt(s.row.entryValidTo)}}</template></el-table-column><el-table-column label="出口有效期"><template #default="s">{{fmt(s.row.exitValidTo)}}</template></el-table-column></el-table></section>
      <section v-if="cardScan.id" class="panel"><div class="scan-head"><h3>卡片资料比对</h3><el-tag :type="cardScan.status==='COMPLETED'?'success':cardScan.status==='FAILED'?'danger':'warning'">{{scanStatus[cardScan.status]||cardScan.status}}</el-tag></div><el-progress v-if="cardScan.status==='PENDING'||cardScan.status==='RUNNING'" :percentage="cardScan.deviceTotal?Math.round((cardScan.deviceCompleted||0)*100/cardScan.deviceTotal):0" :indeterminate="!cardScan.deviceTotal"/><div v-if="cardScan.status==='COMPLETED'" class="scan-cards"><div><b>{{cardScan.uniqueCards}}</b><span>去重后卡片</span></div><div><b>{{cardScan.commonCards}}</b><span>两端共有</span></div><div><b>{{cardScan.onlyEntry}}</b><span>仅入口</span></div><div><b>{{cardScan.onlyExit}}</b><span>仅出口</span></div><div><b>{{cardScan.idNumberCards}}</b><span>身份证格式卡片</span></div><div><b>{{cardScan.conflictCards}}</b><span>人员关联冲突</span></div></div><p class="muted">卡号均加密保存，页面只显示汇总结果。{{cardScan.message}}</p></section>
    </template>

    <template v-else-if="section==='persons'">
      <div class="filters"><el-input v-model="query.keyword" clearable placeholder="姓名、编号、手机号、单位" @keyup.enter="load"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option v-for="(v,k) in label.person" :key="k" :label="v" :value="k"/></el-select><el-button @click="load">查询</el-button></div>
      <section class="panel"><el-table :data="persons"><el-table-column prop="personNo" label="人员编号" min-width="130"/><el-table-column prop="personName" label="姓名"/><el-table-column prop="phone" label="联系电话"/><el-table-column prop="organizationName" label="单位" min-width="130"/><el-table-column prop="departmentName" label="部门"/><el-table-column label="有效期" min-width="170"><template #default="s">{{fmt(s.row.validTo)}}</template></el-table-column><el-table-column label="来源"><template #default="s">{{label.source[s.row.sourceType]||s.row.sourceType}}</template></el-table-column><el-table-column label="设备"><template #default="s">{{s.row.deviceCount||0}} 台</template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="personTagType(s.row.personStatus)">{{label.person[s.row.personStatus]||s.row.personStatus}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="s"><el-button link @click="showPerson(s.row)">详情</el-button><el-button v-if="can('access.person.manage')" link type="primary" @click="editPerson(s.row)">编辑</el-button><el-button v-if="can('access.test-data.delete')" link type="danger" @click="deletePerson(s.row)">彻底删除</el-button></template></el-table-column></el-table></section>
    </template>

    <template v-else-if="section==='visitors'">
      <section class="panel"><h3>访客预约审批</h3><visitor-table :rows="visitors" :can-approve="can('visitor.approve')" :can-revoke="can('access.person.revoke')" :can-delete="can('access.test-data.delete')" @detail="showVisitor" @decision="decideVisitor" @revoke="revokeVisitor" @delete="deleteVisitor" /></section>
      <section v-if="can('visitor.approve')" class="panel"><h3>人员续期审批</h3><renewal-table :rows="renewals" :can-approve="true" @decision="decideRenewal" /></section>
    </template>
    <template v-else-if="section==='events'">
      <el-alert v-if="eventSyncStatus.message" :title="`同步状态：${eventSyncStatus.message}`" :description="eventSyncStatus.completedAt?`完成时间：${fmt(eventSyncStatus.completedAt)}`:''" :type="eventSyncStatus.status==='FAILED'?'error':eventSyncStatus.status==='PARTIAL'?'warning':'info'" show-icon :closable="false" />
      <section class="panel"><event-table :rows="events" :photo-urls="eventPhotoUrls" @snapshot="showEventSnapshot" /><el-pagination class="event-pagination" background layout="total, sizes, prev, pager, next" :total="eventTotal" :current-page="eventPage" :page-size="eventPageSize" :page-sizes="[10,20,50,100]" @current-change="changeEventPage" @size-change="changeEventPageSize"/></section>
    </template>
    <template v-else-if="section==='reviews'">
      <el-alert title="系统只生成复核建议，不会自动删除设备人员。删除建议必须由管理人员确认后再单独执行。" type="warning" show-icon :closable="false" />
      <section class="panel"><el-table :data="reviews"><el-table-column prop="personNo" label="人员编号"/><el-table-column prop="personName" label="姓名"/><el-table-column prop="phone" label="电话"/><el-table-column prop="organizationName" label="单位"/><el-table-column label="最后通行"><template #default="s">{{fmt(s.row.lastPassedAt)}}</template></el-table-column><el-table-column prop="reason" label="复核原因" min-width="190"/><el-table-column label="操作" width="230"><template #default="s"><el-button link type="success" @click="review(s.row,'KEEP')">保留</el-button><el-button link type="warning" @click="review(s.row,'OBSERVE')">继续观察</el-button><el-button link type="danger" @click="review(s.row,'DELETE_RECOMMENDED')">建议删除</el-button></template></el-table-column></el-table></section>
    </template>

    <el-dialog v-model="pointVisible" title="门禁点资料" width="560px"><el-form label-width="100px"><el-form-item label="门禁点编码"><el-input v-model="pointForm.pointCode"/></el-form-item><el-form-item label="门禁点名称"><el-input v-model="pointForm.pointName"/></el-form-item><el-form-item label="安装位置"><el-input v-model="pointForm.location"/></el-form-item><el-form-item label="楼层"><el-input v-model="pointForm.floorCode"/></el-form-item><el-form-item label="说明"><el-input v-model="pointForm.description" type="textarea"/></el-form-item><el-form-item label="启用"><el-switch v-model="pointForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="pointVisible=false">取消</el-button><el-button type="primary" @click="savePoint">保存</el-button></template></el-dialog>
    <el-dialog v-model="deviceVisible" title="添加门禁设备" width="620px"><el-alert title="只需填写连接信息，其余设备资料将自动读取。系统保持只读保护，不会删除或覆盖设备现有人员。" type="warning" :closable="false"/><el-form class="dialog-form" label-width="100px"><el-form-item label="所属门禁点"><el-select v-model="deviceForm.accessPointId"><el-option v-for="p in points.filter((x:any)=>x.enabled)" :key="p.id" :label="p.pointName" :value="p.id"/></el-select></el-form-item><el-form-item label="通行方向"><el-radio-group v-model="deviceForm.direction"><el-radio value="ENTRY">入口</el-radio><el-radio value="EXIT">出口</el-radio></el-radio-group></el-form-item><el-form-item label="设备IP"><el-input v-model="deviceForm.ipAddress" inputmode="decimal" placeholder="例如：192.168.1.100"/></el-form-item><el-form-item label="用户名"><el-input v-model="deviceForm.loginUsername" autocomplete="off" placeholder="设备登录用户名"/></el-form-item><el-form-item label="密码"><el-input v-model="deviceForm.password" type="password" show-password autocomplete="new-password" :placeholder="deviceForm.id?'留空表示不修改密码':'设备登录密码'"/></el-form-item><el-form-item><el-button :loading="probing" @click="probeDevice">连接并自动识别</el-button></el-form-item><div v-if="probeResult.serialNumber" class="probe-result"><b>设备连接成功</b><span>名称：{{probeResult.deviceName||'-'}}</span><span>型号：{{probeResult.model||'-'}}</span><span>序列号：{{probeResult.serialNumber}}</span><span>固件：{{probeResult.firmwareVersion||'-'}}</span></div><el-form-item label="启用"><el-switch v-model="deviceForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="deviceVisible=false">取消</el-button><el-button type="primary" :loading="savingDevice" @click="saveDevice">保存设备</el-button></template></el-dialog>
    <el-dialog v-model="personVisible" title="长期人员资料" width="760px"><el-alert v-if="personForm.sourceType==='DEVICE_LEGACY'" title="这是从设备读取的存量人员。修改本系统资料不会自动覆盖设备中的原始资料。" type="info" :closable="false"/><el-form class="dialog-form grid" label-width="95px"><el-form-item label="人员编号"><el-input v-model="personForm.personNo" placeholder="留空自动生成"/></el-form-item><el-form-item label="姓名"><el-input v-model="personForm.personName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="personForm.phone" inputmode="tel"/></el-form-item><el-form-item label="身份证号"><el-input v-model="personForm.idNumber" maxlength="18" @input="idChanged(personForm)" :placeholder="personForm.id?'不修改可留空':'用于OCR核对及性别判断'"/></el-form-item><el-form-item label="性别"><el-radio-group v-model="personForm.gender"><el-radio value="MALE">男</el-radio><el-radio value="FEMALE">女</el-radio><el-radio value="UNKNOWN">未知</el-radio></el-radio-group></el-form-item><el-form-item label="员工编号"><el-input v-model="personForm.employeeNo"/></el-form-item><el-form-item label="单位类型"><el-select v-model="personForm.affiliationType"><el-option label="铺位商户" value="STALL"/><el-option label="物业" value="PROPERTY"/><el-option label="商管" value="COMMERCIAL"/><el-option label="系统外单位" value="EXTERNAL"/></el-select></el-form-item><el-form-item label="单位名称"><el-input v-model="personForm.organizationName" placeholder="铺位店铺、物业、商管或外部单位"/></el-form-item><el-form-item label="部门"><el-input v-model="personForm.departmentName"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="personForm.validFrom" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="personForm.validTo" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="长期员工留空默认一年"/></el-form-item><el-form-item label="状态"><el-select v-model="personForm.personStatus"><el-option v-for="(v,k) in label.person" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="备注" class="wide"><el-input v-model="personForm.remark"/></el-form-item></el-form><div class="future-upload">身份证正反面、本地OCR和人脸质量检查将在设备人脸接口确认后启用；当前不会覆盖设备原有人脸。</div><template #footer><el-button @click="personVisible=false">取消</el-button><el-button type="primary" @click="savePerson">保存</el-button></template></el-dialog>
    <el-dialog v-model="detailVisible" title="人员及设备原始资料" width="860px">
      <el-descriptions :column="mobile?1:3" border>
        <el-descriptions-item label="姓名">{{detail.personName}}</el-descriptions-item><el-descriptions-item label="系统人员编号">{{detail.personNo}}</el-descriptions-item><el-descriptions-item label="设备原编号">{{detail.employeeNo||'-'}}</el-descriptions-item>
        <el-descriptions-item label="联系电话">{{detail.phone||'-'}}</el-descriptions-item><el-descriptions-item label="身份证号">{{detail.idNumber||'-'}}</el-descriptions-item><el-descriptions-item label="性别">{{detail.gender==='MALE'?'男':detail.gender==='FEMALE'?'女':'未知'}}</el-descriptions-item>
        <el-descriptions-item label="单位类型">{{affiliationLabel[detail.affiliationType]||detail.affiliationType||'-'}}</el-descriptions-item><el-descriptions-item label="单位名称">{{detail.organizationName||'-'}}</el-descriptions-item><el-descriptions-item label="部门">{{detail.departmentName||'-'}}</el-descriptions-item>
      </el-descriptions>
      <h3 class="face-title">设备人脸照片</h3><div class="face-box"><img v-if="faceData" :src="faceData" alt="人员人脸照片"/><el-empty v-else :description="faceMessage" :image-size="60"/></div>
      <h3>设备存量映射</h3><el-table :data="detail.deviceMappings||[]"><el-table-column prop="deviceName" label="设备"/><el-table-column label="方向"><template #default="s">{{label.direction[s.row.direction]}}</template></el-table-column><el-table-column prop="devicePersonName" label="设备原姓名"/><el-table-column prop="devicePersonNo" label="设备人员号"/><el-table-column prop="devicePhone" label="设备联系电话"/><el-table-column label="设备有效期" min-width="170"><template #default="s">{{fmt(s.row.deviceValidTo)}}</template></el-table-column><el-table-column label="人脸"><template #default="s">{{s.row.facePresent?'已登记':'未知'}}</template></el-table-column></el-table>
    </el-dialog>
    <el-dialog v-model="discoveryVisible" title="设备只读探测结果" width="650px"><el-descriptions :column="mobile?1:2" border><el-descriptions-item label="连接状态"><el-tag type="success">连接正常</el-tag></el-descriptions-item><el-descriptions-item label="只读保护">已启用</el-descriptions-item><el-descriptions-item label="设备型号">{{discovery.model||'-'}}</el-descriptions-item><el-descriptions-item label="固件版本">{{discovery.firmwareVersion||'-'}}</el-descriptions-item><el-descriptions-item label="门禁能力">{{discovery.accessControlSupported?'支持':'未识别'}}</el-descriptions-item><el-descriptions-item label="事件能力">{{discovery.eventSubscriptionSupported?'支持':'未识别'}}</el-descriptions-item><el-descriptions-item label="人员读取">{{discovery.personReadSupported?'支持':'未识别'}}</el-descriptions-item><el-descriptions-item label="人员能力描述">{{discovery.personCapabilityAvailable?'可读取':'未识别'}}</el-descriptions-item><el-descriptions-item label="人脸库能力">{{discovery.faceCapabilityAvailable?'可读取':'未识别'}}</el-descriptions-item><el-descriptions-item label="人脸记录能力">{{discovery.faceRecordCapabilityAvailable?'可读取':'未识别'}}</el-descriptions-item><el-descriptions-item label="身份证扩展能力">{{discovery.idCardCapabilityAvailable||discovery.certificateFieldDetected?'已识别':'未识别'}}</el-descriptions-item><el-descriptions-item label="设备人员数">{{discovery.personTotal??'-'}}</el-descriptions-item><el-descriptions-item label="样本人脸/卡片">{{discovery.sampleFaceCount??'-'}} / {{discovery.sampleCardCount??'-'}}</el-descriptions-item><el-descriptions-item label="人员返回字段" :span="mobile?1:2">{{(discovery.personFields||[]).join('、')||'-'}}</el-descriptions-item></el-descriptions><p class="muted">本次仅探测能力和数量，没有导入、修改或删除设备人员。</p></el-dialog>
    <el-dialog v-model="visitorVisible" title="访客门禁申请" width="760px">
      <el-form class="dialog-form grid" label-width="110px">
        <el-form-item label="姓名"><el-input v-model="visitorForm.visitorName"/></el-form-item><el-form-item label="电话"><el-input v-model="visitorForm.visitorPhone" inputmode="tel" maxlength="11"/></el-form-item>
        <el-form-item label="身份证号"><el-input v-model="visitorForm.idNumber" maxlength="18" @input="idChanged(visitorForm)"/></el-form-item><el-form-item label="性别"><el-input :model-value="visitorForm.gender==='MALE'?'男':visitorForm.gender==='FEMALE'?'女':'自动识别'" disabled/></el-form-item>
